package br.com.bora.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.OffsetDateTime; @Entity @Getter @Setter public class Pedido{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public Long lojaId; public String codigo; public Long clienteId; @Enumerated(EnumType.STRING) public StatusPedido status=StatusPedido.RECEBIDO; public BigDecimal valorTotal; public String formaPagamento; public String origem; public String observacao; public OffsetDateTime criadoEm=OffsetDateTime.now(); public OffsetDateTime atualizadoEm=OffsetDateTime.now(); public OffsetDateTime entregueEm; public OffsetDateTime canceladoEm; public String motivoCancelamento; public String entregador; @Column(name="canal_externo") public String canalExterno; @Column(name="id_externo") public String idExterno; @Column(name="taxa_entrega") public BigDecimal taxaEntrega=BigDecimal.ZERO; @Column(name="cliente_telefone") public String clienteTelefone; @Column(name="acerto_id") public Long acertoId; /** PIX online gerado e ainda nao pago. Pedido de balcao, WhatsApp ou marketplace nasce false. */ @Column(name="aguardando_pagamento") public Boolean aguardandoPagamento=false; /** Quando o pagamento online foi confirmado pelo Asaas. */ @Column(name="pago_em") public OffsetDateTime pagoEm; /** O dinheiro desta venda ja entrou? Pedido que espera PIX ainda nao e faturamento. */ public boolean pagamentoPendente(){ return Boolean.TRUE.equals(aguardandoPagamento) && pagoEm==null; }}
